import hashlib,io,json,pathlib,re,secrets,stat,zipfile
from PIL import Image
def validate_payload(data,declared):
    if not isinstance(data,bytes) or len(data)>65536:raise ValueError("upload size limit")
    if declared=="image/png":
        try:
            with Image.open(io.BytesIO(data)) as image:
                if image.format!="PNG" or image.width*image.height>1024:raise ValueError("bounded PNG required")
                image.verify()
            with Image.open(io.BytesIO(data)) as decoded:decoded.load()
        except Exception as exc:raise ValueError("invalid PNG content") from exc
    elif declared=="application/zip":
        try:
            with zipfile.ZipFile(io.BytesIO(data)) as archive:
                infos=archive.infolist();seen=set();total=0
                if not 1<=len(infos)<=8:raise ValueError("archive entry limit")
                for info in infos:
                    name=info.filename.replace("\\","/");parts=pathlib.PurePosixPath(name).parts
                    if not name or name.startswith("/") or ".." in parts or ":" in name or name in seen or stat.S_ISLNK(info.external_attr>>16):raise ValueError("unsafe archive name")
                    seen.add(name)
                    if info.file_size>8192:raise ValueError("archive byte limit")
                    with archive.open(info) as source:
                        while True:
                            chunk=source.read(1024)
                            if not chunk:break
                            total+=len(chunk)
                            if total>8192:raise ValueError("archive total byte limit")
        except (zipfile.BadZipFile,OSError,RuntimeError) as exc:raise ValueError("invalid archive") from exc
    else:raise ValueError("unsupported declared media type")
def paths(root,ident):
    if not isinstance(ident,str) or not re.fullmatch("[0-9a-f]{32}",ident):raise ValueError("opaque object ID required")
    root=pathlib.Path(root);return root/"uploads"/ident,root/"meta"/(ident+".json"),root/"published"/ident
def save(path,meta):
    temporary=path.with_suffix(".tmp");temporary.write_text(json.dumps(meta,sort_keys=True),encoding="utf8");temporary.replace(path)
def load(root,ident):
    blob,path,published=paths(root,ident);return blob,path,published,json.loads(path.read_text(encoding="utf8"))
def blob_bytes(path):
    if path.is_symlink() or not path.is_file():raise ValueError("owned regular object required")
    data=path.read_bytes()
    if len(data)>65536:raise ValueError("changed object size limit")
    return data
