    if not isinstance(name,str) or not name or len(name)>512 or "\x00" in name:raise ValueError("invalid filename metadata")
    validate_payload(data,declared);ident=secrets.token_hex(16)
    for directory in ["uploads","meta","published"]:(pathlib.Path(root)/directory).mkdir(parents=True,exist_ok=True)
    blob,path,_=paths(root,ident);blob.write_bytes(data);save(path,dict(name=name,declared=declared,state="pending",approved_sha=None,published_sha=None))
    return ident
