    if verdict is not True:
        meta.update(state="pending",approved_sha=None);save(path,meta);return False
    data=blob_bytes(blob);validate_payload(data,meta["declared"])
    if hashlib.sha256(data).hexdigest()!=digest:raise ValueError("review digest differs from current object")
    meta.update(state="approved",approved_sha=digest);save(path,meta);return True
def publish(root,ident,publisher_authorized):
